def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    Dn = D(n)
    if Dn == 0:
        return False # Should not happen for n >= 0, but good practice

    # Calculate 20^(n+1)
    try:
        numerator = 20**(n+1)
    except OverflowError:
        # If the number is too large to compute, we must rely on prime factorization/modular arithmetic.
        # However, for n <= 10, 20^11 is manageable. 20^11 = 2 * 10^11 = 2 * 100,000,000,000
        pass

    # Check if Dn divides 20^(n+1)
    if numerator % Dn == 0:
        return True
    else:
        return False

solutions = []
for n in range(11): # Check n = 0, 1, ..., 10
    Dn = D(n)
    is_solution = check_divisibility(n)

    print(f"n={n}: D(n) = {Dn}. Divides 20^{n+1}? {is_solution}")

    if is_solution:
        solutions.append(n)

print(f"Solutions found: {solutions}")

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def get_prime_factors(num):
    factors = set()
    d = 2
    temp = num
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

print("n=0, D(0)=4. Factors:", get_prime_factors(D(0)))
print("n=1, D(1)=15. Factors:", get_prime_factors(D(1)))
print("n=2, D(2)=40. Factors:", get_prime_factors(D(2)))
print("n=3, D(3)=85. Factors:", get_prime_factors(D(3)))
print("n=4, D(4)=156. Factors:", get_prime_factors(D(4)))
